import{_ as o,a0 as s,w as p,s as i,ao as d,I as l,x as e,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"給開源項目貢獻代碼時：先討論，再編碼 | LCTT x X-CMD","titleTemplate":false,"description":"給開源項目貢獻代碼時：先討論，再編碼 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"給開源項目貢獻代碼時：先討論，再編碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"給開源項目貢獻代碼時：先討論，再編碼 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20190218 Talk, then code","title":"給開源項目貢獻代碼時：先討論，再編碼","tag":"202006","desc":""},"relativePath":"202006/20190218 Talk, then code.md","filePath":"[post].md"}'),u={name:"202006/20190218 Talk, then code.md"};function f(h,t,T,m,b,x){const a=s("Link");return p(),i("div",null,[t[15]||(t[15]=d('<h1 id="給開源項目貢獻代碼時-先討論-再編碼" tabindex="-1">給開源項目貢獻代碼時：先討論，再編碼 <a class="header-anchor" href="#給開源項目貢獻代碼時-先討論-再編碼" aria-label="Permalink to “給開源項目貢獻代碼時：先討論，再編碼”">​</a></h1><p>我所參與的開源項目遵循的是一種這樣的理念，我把它描述為 “先討論，再編碼”。我認為一般來説這是開發軟件的好方法，我想花一點時間來談談這種方法的好處。</p><h3 id="避免傷害感情" tabindex="-1">避免傷害感情 <a class="header-anchor" href="#避免傷害感情" aria-label="Permalink to “避免傷害感情”">​</a></h3><p>先討論你想做的改變最重要的原因是避免傷害感情。我經常看到一個貢獻者閉門造車地提交了一個 PR，卻發現他的努力工作被拒絕了。這可能有一堆原因：PR 太大了，PR 沒有遵循本地風格，PR 修復了一個對項目不重要的問題或者最近間接修復了的問題，等等。</p><p>這些問題的根本原因都是缺乏溝通。“先討論，再編碼” 理念的目標不是阻礙你或給你帶來挫折，而是確保一個功能第一次就能正確落地，而不至於產生大量的維護債務。無論是改動的作者，還是審查者，當一個改動突然出現時，並暗示説 “好吧，我已經做完了，你要做的就是合併它，對吧？”，先討論可以讓他們不必揹負傷害感情的情緒負擔。</p><h3 id="討論應該如何進行" tabindex="-1">討論應該如何進行？ <a class="header-anchor" href="#討論應該如何進行" aria-label="Permalink to “討論應該如何進行？”">​</a></h3><p>每一個新功能或錯誤修復都應該在工作開始前與項目的維護者討論。私下試驗是可以的，但不要在沒有討論之前就發送修改。</p><p>對於簡單的改動，“討論” 的定義可以只是 GitHub 議題中的一個設計草圖。如果你的 PR 修復了一個 bug，你應該鏈接到它修復的 bug。如果沒有，你應該先提出一個 bug，等待維護者確認後再發送 PR。這可能看起來有點落後 —— 誰不希望一個 bug 被修復呢 —— 但考慮到這個 bug 可能是對軟件工作方式的誤解，也可能是一個更大問題的症狀，這需要進一步調查。</p><p>對於比較複雜的改動，尤其是功能請求，我建議在發送代碼之前，先分發一份設計文檔並達成一致。這不一定是一個完整的文檔，發一個議題，帶個草圖可能就足夠了，但關鍵是在用代碼搞定之前，先用文字達成一致。</p><p>在任何情況下，你都不應該繼續發送你的代碼，直到維護者同意你的方法是他們所滿意的。拉取請求是日常生活，而不僅僅是為了趕着過節。</p><h3 id="代碼審查-而不是由委員會設計" tabindex="-1">代碼審查，而不是由委員會設計 <a class="header-anchor" href="#代碼審查-而不是由委員會設計" aria-label="Permalink to “代碼審查，而不是由委員會設計”">​</a></h3><p>代碼審查不是爭論設計的地方。這有兩個原因。首先，大多數代碼審查工具都不適合長長的評論會話，GitHub 的 PR 界面在這方面非常糟糕，Gerrit 比較好，但很少有管理員團隊會維護 Gerrit 實例。更重要的是，在代碼審查階段就出現了分歧，説明大家對如何實現這個變化並沒有達成一致。</p><hr><p>討論你想寫的代碼，然後再寫你所討論的代碼。請不要反其道而行之。</p><hr>',15)),l("p",null,[t[1]||(t[1]=e("via: ",-1)),n(a,{href:"https://dave.cheney.net/2019/02/18/talk-then-code"},{default:r(()=>[...t[0]||(t[0]=[e("https://dave.cheney.net/2019/02/18/talk-then-code",-1)])]),_:1})]),l("p",null,[t[6]||(t[6]=e("作者：",-1)),n(a,{href:"https://dave.cheney.net/author/davecheney"},{default:r(()=>[...t[2]||(t[2]=[e("Dave Cheney",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[12]||(t[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const k=o(u,[["render",f]]);export{g as __pageData,k as default};
